  aspect: f32,
  angle: f32,
  clearHistory: f32,
  shiftTexX: f32,
  shiftTexY: f32,
  dispatchOriginX: f32,
  dispatchOriginY: f32,
  copyLayerCount: f32,
  mu: f32,
  workCounterShift: f32,
  rawOriginX: f32,
  rawOriginY: f32,
  tileOriginX: f32,
  tileOriginY: f32,
  neutralSide: f32,
  rotationUnion: f32,
