    clamp(geometry.xy * ratio, vec2<f32>(-64.0), vec2<f32>(64.0)),
    clamp(geometry.z * ratio * ratio, 0.0, 64.0),
    clamp(geometry.w + log(ratio), -64.0, 64.0)
