    let coord = vec2<i32>(
      i32(clamp(liveUv.x * dimsF.x, 0.0, dimsF.x - 1.0)),
      i32(clamp((1.0 - liveUv.y) * dimsF.y, 0.0, dimsF.y - 1.0))
    );
